uv run python -c 'import sys,tempfile; from pathlib import Path; sys.path[:0]=["tests"]; import test_trust_mutants as T; r=Path(tempfile.mkdtemp())/"p"; T.scaffold(r,""); (r/"lean/Demo/Defs.lean").write_text("namespace Demo\n\ndef ref (n : Nat) : Bool := n < 3\n\ndef impl (n : Nat) : Bool := n < 3\n\ntheorem ref_eq_impl : @ref = @impl := by\n  funext n\n  simp [ref, impl]\n\nattribute [csimp] ref_eq_impl\n\nend Demo\n"); (r/"lean/Demo/Inst.lean").write_text("import Demo.Defs\n\nnamespace Demo\n\ndef Small (n : Nat) : Prop := n < 3\n\ntheorem ref_iff (n : Nat) : ref n = true ↔ Small n := by\n  simp [ref, Small]\n\ninstance (n : Nat) : Decidable (Small n) := decidable_of_iff _ (ref_iff n)\n\nexample : impl 0 = impl 0 ∧ Small 2 := by native_decide\n\nend Demo\n"); T.dump(r,Path(tempfile.mkdtemp()),[]); T.git(r,"add","."); T.git(r,"commit","-qm","head"); s=[(m["operator"],m["status"],m["detail"][:90]) for m in T.of(T.tool(r,r.parent/"run")[1],"impl")]; print(s); assert s and not any(x=="KILLED" for _,x,_ in s), s'
